tinymce.PluginManager.add('wbtools', function(editor, url) {

  // 1. Clean Paste Button
  editor.addButton('wb_cleanpaste', {
    icon: 'paste',
    tooltip: 'Clean Paste (Strip Formatting)',
    onclick: function() {
      if (navigator.clipboard && navigator.clipboard.readText) {
        navigator.clipboard.readText().then(function(text) {
          var clean = text.replace(/style="[^"]*"/gi, '').replace(/class="[^"]*"/gi, '');
          editor.insertContent(clean);
          editor.windowManager.alert('Clean content inserted!');
        }).catch(function() {
          editor.windowManager.alert('Unable to read clipboard. Please use Ctrl+V / Cmd+V.');
        });
      } else {
        editor.windowManager.alert('Clipboard API not available. Please use standard paste.');
      }
    }
  });

  // 2. Responsive Video Embed
  editor.addButton('wb_media', {
    icon: 'media',
    tooltip: 'Embed Responsive Video',
    onclick: function() {
      editor.windowManager.open({
        title: 'Insert Video Embed',
        body: [
          { type: 'textbox', name: 'url', label: 'YouTube or Vimeo URL' }
        ],
        onsubmit: function(e) {
          var url = e.data.url || '';
          var embedUrl = url.replace('watch?v=', 'embed/').replace('youtu.be/', 'www.youtube.com/embed/');
          if (embedUrl) {
            var html = '<div style="position:relative;padding-bottom:56.25%;height:0;overflow:hidden;max-width:100%;">' +
                       '<iframe src="' + embedUrl + '" style="position:absolute;top:0;left:0;width:100%;height:100%;" frameborder="0" allowfullscreen></iframe></div>';
            editor.insertContent(html);
          }
        }
      });
    }
  });

  // 3. Responsive Table Builder
  editor.addButton('wb_table', {
    icon: 'table',
    tooltip: 'Insert Styled Responsive Table',
    onclick: function() {
      var tableHtml = '<table style="width:100%; border-collapse:collapse; margin:15px 0;">' +
                      '<thead><tr style="background-color:#f4f4f4;"><th style="padding:8px; border:1px solid #ddd;">Header 1</th><th style="padding:8px; border:1px solid #ddd;">Header 2</th></tr></thead>' +
                      '<tbody><tr><td style="padding:8px; border:1px solid #ddd;">Data 1</td><td style="padding:8px; border:1px solid #ddd;">Data 2</td></tr></tbody></table>';
      editor.insertContent(tableHtml);
    }
  });

  // 4. Accessibility Check
  editor.addButton('wb_a11y', {
    icon: 'checkmark',
    tooltip: 'Run Quick Accessibility Check',
    onclick: function() {
      var imgs = editor.getBody().querySelectorAll('img');
      var missingAlt = 0;
      for (var i = 0; i < imgs.length; i++) {
        var img = imgs[i];
        if (!img.hasAttribute('alt') || img.getAttribute('alt').trim() === '') {
          missingAlt++;
        }
      }
      if (missingAlt > 0) {
        editor.windowManager.alert('Found ' + missingAlt + ' image(s) missing alt text!');
      } else {
        editor.windowManager.alert('Accessibility Check Passed: All images have alt text.');
      }
    }
  });

  return {
    getMetadata: function() {
      return {
        name: 'WebBoss Tools Plugin',
        url: 'https://webboss.io'
      };
    }
  };
});
